#include "PluginEditor.h"
namespace{const juce::Colour bg(0xff08070b),panel(0xff15101b),purple(0xffc000ff),white(0xfff6edff),muted(0xffa99bb4);}
ADVoxAudioProcessorEditor::ADVoxAudioProcessorEditor(ADVoxAudioProcessor& q):AudioProcessorEditor(&q),p(q){
 setSize(760,480);title.setText("AD VOX",juce::dontSendNotification);title.setFont(juce::Font(34.0f,juce::Font::bold));title.setColour(juce::Label::textColourId,purple);addAndMakeVisible(title);
 subtitle.setText("VOCAL CHOP FX  /  EQ + REVERB",juce::dontSendNotification);subtitle.setColour(juce::Label::textColourId,muted);addAndMakeVisible(subtitle);
 const char* names[]={"Neon Tight","Bright Bite","Warm Bounce","Hyper Air","Dream Wash","Clean Snap","Razor Chop","Wide Space","Mid Punch","Glass Vox","Haze Tail","Body Pop","Cyber Shine","Vocal Drive","Crystal Hall","Neon Stack","Deep Echo","Ultra Air","Dry Bounce","Purple Storm"};
 for(int i=0;i<20;++i)presets.addItem(juce::String(i+1).paddedLeft('0',2)+"  "+names[i],i+1);
 presets.setSelectedId(1,juce::dontSendNotification);presets.setColour(juce::ComboBox::backgroundColourId,panel);presets.setColour(juce::ComboBox::textColourId,white);presets.setColour(juce::ComboBox::outlineColourId,purple);presets.onChange=[this]{p.loadPreset(presets.getSelectedId()-1);};addAndMakeVisible(presets);
 const char* ids[]={"GAIN","LOW","MID","HIGH","REVERB","DECAY"};const char* ns[]={"OUTPUT","LOW EQ","MID EQ","HIGH EQ","REVERB","DECAY"};
 double mins[]={0,-12,-12,-12,0,.1},maxs[]={2,12,12,12,100,8},steps[]={.01,.1,.1,.1,1,.1};const char* suf[]={"x"," dB"," dB"," dB","%"," s"};
 for(int i=0;i<6;++i){s[i].setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);s[i].setTextBoxStyle(juce::Slider::TextBoxBelow,false,70,20);s[i].setRange(mins[i],maxs[i],steps[i]);s[i].setTextValueSuffix(suf[i]);s[i].setColour(juce::Slider::rotarySliderFillColourId,purple);s[i].setColour(juce::Slider::rotarySliderOutlineColourId,juce::Colour(0xff35203f));s[i].setColour(juce::Slider::thumbColourId,white);s[i].setColour(juce::Slider::textBoxTextColourId,white);s[i].setColour(juce::Slider::textBoxBackgroundColourId,panel);addAndMakeVisible(s[i]);labels[i].setText(ns[i],juce::dontSendNotification);labels[i].setJustificationType(juce::Justification::centred);labels[i].setColour(juce::Label::textColourId,white);addAndMakeVisible(labels[i]);att[i]=std::make_unique<juce::AudioProcessorValueTreeState::SliderAttachment>(p.parameters,ids[i],s[i]);}
}
void ADVoxAudioProcessorEditor::paint(juce::Graphics& g){g.fillAll(bg);g.setColour(panel);g.fillRoundedRectangle(getLocalBounds().toFloat().reduced(14),18);g.setColour(purple);g.drawRoundedRectangle(getLocalBounds().toFloat().reduced(14),18,1.5f);g.setColour(purple.withAlpha(.12f));for(int x=20;x<getWidth();x+=32)g.drawVerticalLine(x,20,(float)getHeight()-20);g.setColour(muted);g.setFont(12);g.drawText("20 STARTER PRESETS  /  EQ + REVERB",30,getHeight()-35,getWidth()-60,18,juce::Justification::centredLeft);}
void ADVoxAudioProcessorEditor::resized(){title.setBounds(32,22,250,46);subtitle.setBounds(34,66,320,22);presets.setBounds(380,38,330,34);for(int i=0;i<6;++i){int x=24+i*120;labels[i].setBounds(x,145,110,24);s[i].setBounds(x,170,110,165);}}
